        spec.entails(always(p.and(next).implies(later(p).or(later(q))))),
        spec.entails(always(p.and(next).and(forward).implies(later(q)))),
        spec.entails(always(next)),
        spec.entails(always(p).leads_to(forward)),
    ensures spec.entails(p.leads_to(q)),
	{
		unimplemented!()
	}

pub proof fn wf1<T>(spec: TempPred<T>, next: ActionPred<T>, forward: ActionPred<T>, p: StatePred<T>, q: StatePred<T>)
    requires
        forall |s, s_prime: T| p(s) && #[trigger] next(s, s_prime) ==> p(s_prime) || q(s_prime),
        forall |s, s_prime: T| p(s) && #[trigger] next(s, s_prime) && forward(s, s_prime) ==> q(s_prime),
        forall |s: T| #[trigger] p(s) ==> enabled(forward)(s),
        spec.entails(always(lift_action(next))),
        spec.entails(weak_fairness(forward)),
    ensures spec.entails(lift_state(p).leads_to(lift_state(q))),
{
    // We apply wf1_variant_temp with:
    // - p_temp = lift_state(p)
    // - q_temp = lift_state(q)
    // - next_temp = lift_action(next)
    // - forward_temp = lift_action(forward)

    let p_temp = lift_state(p);
    let q_temp = lift_state(q);
    let next_temp = lift_action(next);
    let forward_temp = lift_action(forward);

    // Prove condition 1: spec.entails(always(p_temp.and(next_temp).implies(later(p_temp).or(later(q_temp)))))
    assert forall |ex: Execution<T>| spec.satisfied_by(ex) implies
        always(p_temp.and(next_temp).implies(later(p_temp).or(later(q_temp)))).satisfied_by(ex)
    by {
        assert forall |i: nat| p_temp.and(next_temp).implies(later(p_temp).or(later(q_temp))).satisfied_by(#[trigger] ex.suffix(i))
        by {
            let ex_i = ex.suffix(i);
            // If p(head) and next(head, head_next) then p(head_next) || q(head_next)
            // head_next of ex.suffix(i) = ex.suffix(i+1).head() = p or q
            if p_temp.and(next_temp).satisfied_by(ex_i) {
                // p(ex_i.head()) and next(ex_i.head(), ex_i.head_next())
                let s = ex_i.head();
                let s_prime = ex_i.head_next();
                assert(p(s) && next(s, s_prime));
                // By precondition 1: p(s_prime) || q(s_prime)
                assert(p(s_prime) || q(s_prime));
                // s_prime = ex_i.suffix(1).head()
                // later(p_temp) = p_temp.satisfied_by(ex_i.suffix(1))
                // ex_i.suffix(1).head() = (ex_i.nat_to_state)(0 + 1) = (ex_i.nat_to_state)(1) = ex_i.head_next() = s_prime
                assert(ex_i.suffix(1).head() == s_prime) by {
                    // ex_i.suffix(1).nat_to_state = |j: nat| (ex_i.nat_to_state)(j + 1)
                    // ex_i.suffix(1).head() = (ex_i.suffix(1).nat_to_state)(0) = (ex_i.nat_to_state)(0 + 1) = (ex_i.nat_to_state)(1)
                    // ex_i.head_next() = (ex_i.nat_to_state)(1)
                };
                // So later(p_temp).satisfied_by(ex_i) = p(s_prime)
                // and later(q_temp).satisfied_by(ex_i) = q(s_prime)
                assert(later(p_temp).or(later(q_temp)).satisfied_by(ex_i));
            }
        };
    };
    assert(spec.entails(always(p_temp.and(next_temp).implies(later(p_temp).or(later(q_temp))))));

    // Prove condition 2: spec.entails(always(p_temp.and(next_temp).and(forward_temp).implies(later(q_temp))))
    assert forall |ex: Execution<T>| spec.satisfied_by(ex) implies
        always(p_temp.and(next_temp).and(forward_temp).implies(later(q_temp))).satisfied_by(ex)
    by {
        assert forall |i: nat| p_temp.and(next_temp).and(forward_temp).implies(later(q_temp)).satisfied_by(#[trigger] ex.suffix(i))
        by {
            let ex_i = ex.suffix(i);
            if p_temp.and(next_temp).and(forward_temp).satisfied_by(ex_i) {
                let s = ex_i.head();
                let s_prime = ex_i.head_next();
                assert(p(s) && next(s, s_prime) && forward(s, s_prime));
                assert(q(s_prime));
                assert(ex_i.suffix(1).head() == s_prime);
                assert(later(q_temp).satisfied_by(ex_i));
            }
        };
    };
    assert(spec.entails(always(p_temp.and(next_temp).and(forward_temp).implies(later(q_temp)))));

    // Condition 3: spec.entails(always(next_temp)) is given directly
    assert(spec.entails(always(next_temp)));

    // Prove condition 4: spec.entails(always(p_temp).leads_to(forward_temp))
    // always(p_temp).leads_to(forward_temp) = always(always(p_temp).implies(eventually(forward_temp)))
    // We need: for any execution ex satisfying spec and any position i,
    //   if always(p_temp).satisfied_by(ex.suffix(i)), then eventually(forward_temp).satisfied_by(ex.suffix(i))
    // always(p_temp).satisfied_by(ex.suffix(i)) means p holds at all positions from i onwards
    // We need to show: exists j, forward(s_{i+j}, s_{i+j+1})
    // We know weak_fairness(forward) = always(lift_state(enabled(forward))).leads_to(lift_action(forward))
    // We know p(s) ==> enabled(forward)(s) for all s
    // Since p holds at all positions from i onwards, enabled(forward) holds at all positions from i onwards
    // So always(lift_state(enabled(forward))) holds from i onwards
    // By weak_fairness, eventually(lift_action(forward)) holds from i onwards
    assert forall |ex: Execution<T>| spec.satisfied_by(ex) implies
        always(p_temp).leads_to(forward_temp).satisfied_by(ex)
    by {
        assert forall |i: nat| p_temp.implies(eventually(forward_temp)).satisfied_by(#[trigger] ex.suffix(i)) by {
            // This says: if p_temp holds at ex.suffix(i), eventually(forward_temp) holds at ex.suffix(i)
            // But actually always(p_temp).leads_to(forward_temp) = always(always(p_temp).implies(eventually(forward_temp)))
            // Hmm, actually leads_to is defined as always(self.implies(eventually(other)))
            // So always(p_temp).leads_to(forward_temp) = always(always(p_temp).implies(eventually(forward_temp)))
            // i.e., for all i: if always(p_temp) holds at ex.suffix(i), then eventually(forward_temp) holds at ex.suffix(i)
        };
    };

    // Let me reconsider - leads_to(self, other) = always(self.implies(eventually(other)))
    // always(p_temp).leads_to(forward_temp) = always(always(p_temp).implies(eventually(forward_temp)))
    assert forall |ex: Execution<T>| spec.satisfied_by(ex) implies
        always(always(p_temp).implies(eventually(forward_temp))).satisfied_by(ex)
    by {
        assert forall |i: nat| always(p_temp).implies(eventually(forward_temp)).satisfied_by(#[trigger] ex.suffix(i))
        by {
            let ex_i = ex.suffix(i);
            if always(p_temp).satisfied_by(ex_i) {
                // p holds at every position starting from i
                // So enabled(forward) holds at every position starting from i
                // So always(lift_state(enabled(forward))) holds from i
                // By weak_fairness, eventually(forward_temp) holds from i

                // First show always(lift_state(enabled(forward))).satisfied_by(ex_i)
                assert(always(lift_state(enabled(forward))).satisfied_by(ex_i)) by {
                    assert forall |j: nat| lift_state(enabled(forward)).satisfied_by(#[trigger] ex_i.suffix(j))
                    by {
                        // p(ex_i.suffix(j).head()) since always(p_temp) holds at ex_i
                        let s = ex_i.suffix(j).head();
                        // always(p_temp).satisfied_by(ex_i) means forall j, p_temp.satisfied_by(ex_i.suffix(j))
                        assert(p_temp.satisfied_by(ex_i.suffix(j)));
                        assert(p(s));
                        // p(s) ==> enabled(forward)(s)
                        assert(enabled(forward)(s));
                        assert(lift_state(enabled(forward)).satisfied_by(ex_i.suffix(j)));
                    };
                };

                // Now apply weak_fairness
                // weak_fairness(forward).satisfied_by(ex) and spec.satisfied_by(ex)
                // We need weak_fairness(forward).satisfied_by(ex_i) 
                // But weak_fairness is a property of spec, not just ex...
                // We need: always(lift_state(enabled(forward))).implies(eventually(lift_action(forward))).satisfied_by(ex_i)
                // This follows from weak_fairness(forward).satisfied_by(ex) applied at position i

                // spec.entails(weak_fairness(forward)) means valid(spec.implies(weak_fairness(forward)))
                // So spec.satisfied_by(ex) ==> weak_fairness(forward).satisfied_by(ex)
                assert(weak_fairness(forward).satisfied_by(ex));
                // weak_fairness(forward) = always(lift_state(enabled(forward))).leads_to(lift_action(forward))
                //   = always(always(lift_state(enabled(forward))).implies(eventually(lift_action(forward))))
                // So for all j, (always(lift_state(enabled(forward))).implies(eventually(lift_action(forward)))).satisfied_by(ex.suffix(j))
                // In particular, for j = i, this holds at ex.suffix(i) = ex_i
                weak_fairness_unfold(ex, forward);
                // This gives forall j, always(lift_state(enabled(forward))).implies(eventually(lift_action(forward))).satisfied_by(ex.suffix(j))
                // For j = i:
                assert(always(lift_state(enabled(forward))).implies(eventually(lift_action(forward))).satisfied_by(ex_i));
                implies_apply(ex_i, always(lift_state(enabled(forward))), eventually(lift_action(forward)));
                assert(eventually(lift_action(forward)).satisfied_by(ex_i));
                assert(eventually(forward_temp).satisfied_by(ex_i));
            }
        };
    };
    assert(spec.entails(always(p_temp).leads_to(forward_temp)));

    // Now call wf1_variant_temp
    wf1_variant_temp(spec, next_temp, forward_temp, p_temp, q_temp);
}


}
