        always(p_temp.and(next_temp).and(forward_temp).implies(later(q_temp))).satisfied_by(ex)
    by {
        assert forall |i: nat| p_temp.and(next_temp).and(forward_temp).implies(later(q_temp)).satisfied_by(#[trigger] ex.suffix(i))
        by {
            let ex_i = ex.suffix(i);
