    by {
        assert forall |i: nat| always(p_temp).implies(eventually(forward_temp)).satisfied_by(#[trigger] ex.suffix(i))
        by {
            let ex_i = ex.suffix(i);
            if always(p_temp).satisfied_by(ex_i) {
                // p holds at every position starting from i
                // So enabled(forward) holds at every position starting from i
                // So always(lift_state(enabled(forward))) holds from i
                // By weak_fairness, eventually(forward_temp) holds from i

                // First show always(lift_state(enabled(forward))).satisfied_by(ex_i)
                assert(always(lift_state(enabled(forward))).satisfied_by(ex_i)) by {
