            let ex_i = ex.suffix(i);
            if p_temp.and(next_temp).satisfied_by(ex_i) {
                let s = ex_i.head();
                let s_prime = ex_i.head_next();
                assert(p(s));
                assert(next(s, s_prime));
                assert(p(s_prime) || q(s_prime));
                assert(ex_i.suffix(1).head() == s_prime) by {
                    assert((ex_i.suffix(1).nat_to_state)(0) == (ex_i.nat_to_state)(0 + 1));
                };
                assert(later(p_temp).or(later(q_temp)).satisfied_by(ex_i));
            }
        };
    };
    assert(spec.entails(always(p_temp.and(next_temp).implies(later(p_temp).or(later(q_temp))))));

    // Prove condition 2: spec.entails(always(p_temp.and(next_temp).and(forward_temp).implies(later(q_temp))))
    assert forall |ex: Execution<T>| spec.satisfied_by(ex) implies
        always(p_temp.and(next_temp).and(forward_temp).implies(later(q_temp))).satisfied_by(ex)
    by {
        assert forall |i: nat| #[trigger] p_temp.and(next_temp).and(forward_temp).implies(later(q_temp)).satisfied_by(ex.suffix(i))
        by {
            let ex_i = ex.suffix(i);
            if p_temp.and(next_temp).and(forward_temp).satisfied_by(ex_i) {
                let s = ex_i.head();
                let s_prime = ex_i.head_next();
                assert(p(s));
                assert(next(s, s_prime));
                assert(forward(s, s_prime));
                assert(q(s_prime));
                assert(ex_i.suffix(1).head() == s_prime) by {
                    assert((ex_i.suffix(1).nat_to_state)(0) == (ex_i.nat_to_state)(0 + 1));
                };
                assert(later(q_temp).satisfied_by(ex_i));
            }
        };
    };
    assert(spec.entails(always(p_temp.and(next_temp).and(forward_temp).implies(later(q_temp)))));

    // Condition 3 is directly given
    assert(spec.entails(always(next_temp)));

    // Prove condition 4: spec.entails(always(p_temp).leads_to(forward_temp))
    // leads_to definition: always(p_temp).leads_to(forward_temp) = always(always(p_temp).implies(eventually(forward_temp)))
    assert forall |ex: Execution<T>| spec.satisfied_by(ex) implies
        always(always(p_temp).implies(eventually(forward_temp))).satisfied_by(ex)
    by {
        // Get weak_fairness at ex
        entails_apply(spec, weak_fairness(forward), ex);
        assert(weak_fairness(forward).satisfied_by(ex));
        // Unfold weak_fairness to get for all i, the implication holds
        weak_fairness_unfold(ex, forward);
        // for all i: always(lift_state(enabled(forward))).implies(eventually(lift_action(forward))).satisfied_by(ex.suffix(i))

        assert forall |i: nat| #[trigger] always(p_temp).implies(eventually(forward_temp)).satisfied_by(ex.suffix(i))
        by {
            let ex_i = ex.suffix(i);
            if always(p_temp).satisfied_by(ex_i) {
                // Show always(lift_state(enabled(forward))).satisfied_by(ex_i)
                assert(always(lift_state(enabled(forward))).satisfied_by(ex_i)) by {
                    assert forall |j: nat| #[trigger] lift_state(enabled(forward)).satisfied_by(ex_i.suffix(j))
                    by {
                        assert(p_temp.satisfied_by(ex_i.suffix(j)));
                        let s = ex_i.suffix(j).head();
                        assert(p(s));
                        assert(enabled(forward)(s));
                        assert(lift_state(enabled(forward)).satisfied_by(ex_i.suffix(j)));
                    };
                };
                // Apply weak_fairness at ex_i (via weak_fairness_unfold result at i)
                implies_apply(ex_i, always(lift_state(enabled(forward))), eventually(lift_action(forward)));
                assert(eventually(forward_temp).satisfied_by(ex_i));
            }
        };
    };
    assert(spec.entails(always(p_temp).leads_to(forward_temp)));

    // Apply wf1_variant_temp
    wf1_variant_temp(spec, next_temp, forward_temp, p_temp, q_temp);
}

}
